"""Auto-generated inventory of all produced artifacts (reviewer P1-01).

Writes data/metadata/inventory_summary.json so the report can state exactly
which files were generated by this run and when — no stale, hand-maintained
file lists.
"""
import json
import logging
import subprocess
from datetime import datetime
from pathlib import Path

logger = logging.getLogger(__name__)


def _git_commit(base_dir: Path) -> str:
    try:
        r = subprocess.run(["git", "rev-parse", "HEAD"], cwd=str(base_dir),
                           capture_output=True, text=True, timeout=5)
        return r.stdout.strip() or "unknown"
    except Exception:
        return "unknown"


def _scan_dir(d: Path) -> list:
    if not d.exists():
        return []
    out = []
    for p in sorted(d.iterdir()):
        if p.is_file():
            out.append({
                "filename": p.name,
                "size_bytes": p.stat().st_size,
                "modified": datetime.fromtimestamp(p.stat().st_mtime).isoformat(),
            })
        elif p.is_dir() and p.name == "raw":
            continue
    return out


def _csv_rows(p: Path):
    try:
        import pandas as pd
        return int(len(pd.read_csv(p)))
    except Exception:
        return None


def _count_api_endpoints(base_dir: Path) -> dict:
    """Count live API endpoints straight from app.routes (reviewer P1-01).

    Reads the FastAPI application object at runtime instead of grepping
    '@app.<method>(' decorators out of the source text, so it stays correct
    under route prefixes / routers / renamed decorators and matches the
    reviewer's "đọc trực tiếp app.routes" requirement.
    """
    method_counts = {"GET": 0, "POST": 0, "PUT": 0, "DELETE": 0}
    try:
        from src.api import app
        from fastapi.routing import APIRoute
    except Exception as e:  # pragma: no cover - environment-dependent
        logger.warning(f"Could not import app to count API endpoints: {e}")
        return {**dict(method_counts), "total": 0}

    # FastAPI auto-registers /openapi.json, /docs, /docs/oauth2-redirect and
    # /redoc; they are starlette Route objects today, but filter by path too so
    # the count stays limited to authored endpoints in any FastAPI version.
    auto_doc_paths = {"/openapi.json", "/docs", "/docs/oauth2-redirect", "/redoc"}
    for route in app.routes:
        if not isinstance(route, APIRoute):
            continue
        if route.path in auto_doc_paths:
            continue
        for method in (route.methods or set()):
            up = method.upper()
            if up in method_counts:
                method_counts[up] += 1
    counts = dict(method_counts)
    counts["total"] = sum(counts.values())
    return counts


def _count_test_cases(base_dir: Path) -> dict:
    tests_dir = base_dir / "tests"
    counts = {"test_files": 0, "test_cases": 0}
    if not tests_dir.exists():
        return counts
    for p in sorted(tests_dir.glob("test_*.py")):
        text = p.read_text(encoding="utf-8", errors="ignore")
        n = len([1 for line in text.splitlines()
                 if line.strip().startswith("def test_")])
        counts["test_files"] += 1
        counts["test_cases"] += n
    return counts


def _count_models(base_dir: Path) -> dict:
    models_dir = base_dir / "models"
    counts = {"total_model_files": 0}
    if models_dir.exists():
        joblib = list(models_dir.glob("*.joblib"))
        counts["total_model_files"] = len(joblib)
        from collections import Counter
        per_type = Counter()
        for f in joblib:
            name = f.name.replace("_model.joblib", "")
            if name.endswith("_lightgbm"):
                per_type["lightgbm"] += 1
            elif name.endswith("_xgboost"):
                per_type["xgboost"] += 1
            else:
                per_type["other"] += 1
        counts["per_model_type"] = dict(per_type)
    return counts


def generate_inventory(base_dir: Path) -> dict:
    base_dir = Path(base_dir)

    dirs = {
        "data/processed": "data_processed",
        "data/metadata": "data_metadata",
        "outputs/forecasts": "outputs_forecasts",
        "outputs/figures": "outputs_figures",
        "models": "models",
        "logs": "logs",
    }

    inventory = {
        "generated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "git_commit": _git_commit(base_dir),
        "categories": {},
    }

    for rel, key in dirs.items():
        files = _scan_dir(base_dir / rel)
        for f in files:
            if rel == "outputs/forecasts" and f["filename"].endswith(".csv"):
                f["n_rows"] = _csv_rows(base_dir / rel / f["filename"])
        inventory["categories"][key] = {
            "directory": rel,
            "n_files": len(files),
            "files": files,
        }

    # P1-01: unified counts so the report has ONE source of truth.
    inventory["counts"] = {
        "api_endpoints": _count_api_endpoints(base_dir),
        "tests": _count_test_cases(base_dir),
        "models": _count_models(base_dir),
    }
    raw_dir = base_dir / "data" / "raw"
    if raw_dir.exists():
        raw_files = [p for p in sorted(raw_dir.glob("*.xlsx"))]
        inventory["counts"]["raw_data"] = {
            "n_files": len(raw_files),
            "n_rows": None,
        }
    manifest = base_dir / "data" / "metadata" / "data_manifest.csv"
    if manifest.exists():
        try:
            import pandas as pd
            mf = pd.read_csv(manifest)
            inventory["counts"]["raw_data"]["n_files"] = int(len(mf))
            inventory["counts"]["raw_data"]["n_rows"] = int(mf["n_rows"].sum()) if "n_rows" in mf.columns else None
        except Exception:
            pass
    wf = base_dir / "data" / "metadata" / "walk_forward_summary.json"
    if wf.exists():
        try:
            with open(wf, "r", encoding="utf-8") as f:
                inventory["counts"]["walk_forward_baseline_evaluations"] = len(json.load(f))
        except Exception:
            pass
    ev = base_dir / "outputs" / "forecasts" / "evaluation_metrics.csv"
    if ev.exists():
        try:
            import pandas as pd
            df = pd.read_csv(ev)
            inventory["counts"]["evaluation_rows"] = int(len(df))
            if "model" in df.columns:
                inventory["counts"]["evaluation_by_model"] = {
                    str(k): int(v) for k, v in df["model"].value_counts().items()}
        except Exception:
            pass

    out_path = base_dir / "data" / "metadata" / "inventory_summary.json"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(inventory, f, indent=2, ensure_ascii=False)

    total_files = sum(v["n_files"] for v in inventory["categories"].values())
    logger.info(f"Inventory written to {out_path} ({total_files} files across "
                f"{len(inventory['categories'])} categories)")
    return inventory
